// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io/

// Palette from https://kgolid.github.io/chromotome-site/ (sprague)

var div_modes = [];
var n_modes = 14;
var palette = [[34, 30, 31], [252, 239, 223], [236, 47, 40], [248, 205, 40], [30, 149, 187], [251, 170, 179]];
var colors = [];
var count;

function setup() {
  createCanvas(600, 600);
  //// noLoop() removed for animation
  fill(20);
	stroke(30);
	strokeWeight(2);
	stroke(palette[0]);
	rectMode(CENTER);
  generate_modes();
  generate_colors();
}

function draw() {
  background(30);
  let f = map(sin(frameCount/100), -1, 1, 0, 1);
  let n = 3;
  count = 0;
  drawEllipses(0, 0, width, f, n);
  if (f < 1e-3) {
    generate_modes();
    generate_colors();
  }
}

function drawEllipses(x, y, s, f, n) {
  push();
  translate(x+s/2, y+s/2);
  let sum = 0;
  for (let i = 1; i <= n; i++) {
    sum += pow(f, i);
  }
  let max_d = s/(1+2*sum);
  let d = max_d;
  let prev_d = d;
  let pos = 0;
  fill(colors[count++]);
  rect(0, 0, max_d);
  for (let i = 1; i <= n; i++) {
    pos -= d/2;
    d *= f;
    pos -= d/2;
    prev_d = d;
    fill(colors[count++]);
    rect(pos, 0, d, max_d);
    fill(colors[count++]);
    rect(-pos, 0, d, max_d);
    fill(colors[count++]);
    rect(0, pos, max_d, d);
    fill(colors[count++]);
    rect(0, -pos, max_d, d);
  }
  pop();
  if (n > 0) {
    let new_s = (s-max_d)/2;
    drawEllipses(x, y, new_s, new_f(f, div_modes[0]), n-1);
    drawEllipses(x, y+s-new_s, new_s, new_f(f, div_modes[1]), n-1);
    drawEllipses(x+s-new_s, y, new_s, new_f(f, div_modes[2]), n-1);
    drawEllipses(x+s-new_s, y+s-new_s, new_s, new_f(f, div_modes[3]), n-1);
  }
}

function generate_modes() {
  div_modes = [];
  for (let i = 0; i < 4; i++) {
    div_modes.push(floor(random(n_modes)));
  }
}

function generate_colors() {
  colors = [];
  for (let i = 0; i < 193; i ++) {
    colors.push(random(palette));
  }
  colors[0] = palette[0];
}

function new_f(f, mode) {
  let res;
  switch (floor(mode/2)) {
    case 0:
      res = f;
      break;
    case 1:
      res = cos(f*PI/2)*sin(f*PI/2)*2;
      break;
    case 2:
      res = pow(f, 2);
      break;
    case 3:
      res = sqrt(f);
      break;
    case 4:
      res = pow(f, 10);
      break;
    case 5:
      res = pow(f, 1/10);
      break;
    case 6:
      res = -(cos(PI*f)-1)/2;
  }
  return flip(res, mode%2);
}

function flip(f, bit) {
  if (bit == 0) {
    return f;
  }
  return 1-f;
}
